  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "C10: In healthy volunteers, the 1500 mg tablet of this piperazine/aminopyrimidine analogue gave 77% absolute oral bioavailability in the fed state; the high transfer score and shared piperazine/heteroaromatic core support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "C04: The same analogue in fasted healthy volunteers had 57% absolute oral bioavailability, showing high F independent of food and supporting high.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "C05: A 180 mg oral dose of the same analogue in healthy volunteers gave approximately 46% bioavailability, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "C08: Trametinib, a complex fused heteroaromatic with an acetamide and cyclopropyl group, had 72% oral bioavailability in fasted patients, supporting high F for the query's similar heteroaromatic/lipophilic architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "C07: Brepocitinib, a pyrimidine-containing kinase inhibitor with a basic bicyclic amine, had 75% absolute bioavailability in humans, supporting high F despite ionizable centers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "C12: Nevirapine extended-release had 80–94% absolute oral bioavailability in humans, supporting high F for a related heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "C01: Olaparib, a piperazine-containing drug, had simulated absolute oral bioavailability of 0.72, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "C09: A structurally similar piperazine/pyrimidine-fused lactam was reported to have approximately 20–25% oral bioavailability, still meeting the ≥20% threshold and therefore supportive, though with a narrower margin.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High-transfer human absolute bioavailability data for structurally related piperazine/aminopyrimidine and heteroaromatic drugs consistently show F = 46–94%, outweighing the uncertain physicochemical prior; the only borderline result (~20–25%) still meets the ≥20% threshold. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule.",
    "The low-transfer phenylpiperazine records (C11, C02) are not applicable due to zero transfer likelihood; C02's wide 12–84% range is uninformative.",
    "Potential efflux or metabolic clearance specific to the query's secondary piperazine is not directly covered by the high-transfer analogues."
